106	    err_msg.target_angular_z_radps = res.cmd.angular_z;
107	    err_msg.actual_linear_x_mps = current_linear_speed_;
108	    err_msg.nearest_waypoint_index = static_cast<int32_t>(res.nearest_index);
109	    err_msg.arrived = res.goal_reached;
110	  } else {
111	    auto res = pp_controller_->Compute(current_pose_);
112	    cmd.linear.x = res.cmd.linear_x;
113	    cmd.angular.z = res.cmd.angular_z;
114	
115	    err_msg.lateral_error_m = res.lateral_error;
116	    err_msg.heading_error_rad = res.heading_error;
117	    err_msg.target_linear_x_mps = res.cmd.linear_x;
