12	SafetyGateNode::SafetyGateNode(const rclcpp::NodeOptions& options)
13	    : rclcpp::Node("safety_gate_node", options) {
14	  declare_parameter("max_linear_x_mps", 1.5);
15	  declare_parameter("max_linear_y_mps", 1.0);
16	  declare_parameter("max_angular_z_radps", 2.0);
17	  declare_parameter("heartbeat_timeout_ms", 500);
18	  declare_parameter("soft_timeout_ms", 2000);
19	  // M5：降级限速阈值参数化（原为硬编码 ±0.2，与 max_* 参数体系脱节）
20	  declare_parameter("degraded_max_linear_x_mps", 0.2);
21	
22	  // M4：参数在构造期读取并缓存——watchdog/gate 配置本就是启动期固定，
23	  // 周期路径（10Hz/50Hz）不再重复 get_parameter。
24	  heartbeat_timeout_ =
25	      std::chrono::milliseconds(get_parameter("heartbeat_timeout_ms").as_int());
26	  degraded_max_linear_x_mps_ = get_parameter("degraded_max_linear_x_mps").as_double();
27	
28	  amr_dispatcher_core::safety::CmdVelGateConfig gate_cfg;
29	  gate_cfg.max_linear_x_mps = get_parameter("max_linear_x_mps").as_double();
30	  gate_cfg.max_linear_y_mps = get_parameter("max_linear_y_mps").as_double();
31	  gate_cfg.max_angular_z_radps = get_parameter("max_angular_z_radps").as_double();
32	  gate_cfg.source_blocked = [this](const std::string& src) {
33	    if (src == "estop") return estop_active_ || auto_fault_latched_;
34	    if (src == "bumper") return bumper_active_;
35	    if (src.find("watchdog") != std::string::npos) return true;
36	    return false;
37	  };
38	
39	  gate_ = std::make_unique<amr_dispatcher_core::safety::CmdVelGate>(gate_cfg);
40	
41	  amr_dispatcher_core::safety::WatchdogConfig wd_cfg;
42	  wd_cfg.heartbeat_timeout = heartbeat_timeout_;
43	  wd_cfg.soft_timeout = std::chrono::milliseconds(get_parameter("soft_timeout_ms").as_int());
44	  watchdog_ = std::make_unique<amr_dispatcher_core::safety::SafetyWatchdog>(wd_cfg);
45	
46	  amr_dispatcher_core::safety::SupervisorConfig sup_cfg;
47	  sup_cfg.startup_grace = 2000ms;
48	  sup_cfg.command_cooldown = 500ms;
49	  sup_cfg.auto_clear = true;
50	  fault_supervisor_ = std::make_unique<amr_dispatcher_core::safety::FaultSupervisor>(sup_cfg);
51	
52	  watched_nodes_ = {"chassis_driver", "path_tracker"};
53	  for (const auto& node : watched_nodes_) {
54	    watchdog_->FeedHeartbeat(node);
55	  }
56	
57	  raw_cmd_vel_sub_ = create_subscription<geometry_msgs::msg::Twist>(
58	      "/cmd_vel_raw", 10,
59	      std::bind(&SafetyGateNode::RawCmdVelCallback, this, std::placeholders::_1));
60	
61	  teleop_cmd_vel_sub_ = create_subscription<geometry_msgs::msg::Twist>(
62	      "/cmd_vel_teleop", 10,
63	      [this](const geometry_msgs::msg::Twist::SharedPtr msg) {
64	        if (manual_takeover_active_) {
65	          RawCmdVelCallback(msg);
66	        }
67	      });
68	
69	  manual_takeover_sub_ = create_subscription<std_msgs::msg::Bool>(
70	      "/safety/manual_takeover", 10,
71	      [this](const std_msgs::msg::Bool::SharedPtr msg) {
72	        manual_takeover_active_ = msg->data;
73	        RCLCPP_INFO(get_logger(), "Manual takeover changed: %s", manual_takeover_active_ ? "ON" : "OFF");
74	      });
75	
76	  estop_sub_ = create_subscription<std_msgs::msg::Bool>(
77	      "/safety/estop", 10,
78	      std::bind(&SafetyGateNode::EstopCallback, this, std::placeholders::_1));
79	
80	  bumper_sub_ = create_subscription<std_msgs::msg::Bool>(
81	      "/safety/bumper", 10,
82	      std::bind(&SafetyGateNode::BumperCallback, this, std::placeholders::_1));
83	
84	  // B1 心跳分源：每条心跳只 Feed 对应来源，一侧停止不会"替"另一侧续命。
85	  heartbeat_chassis_sub_ = create_subscription<std_msgs::msg::Bool>(
86	      "/safety/heartbeat/chassis_driver", 10,
87	      [this](const std_msgs::msg::Bool::SharedPtr msg) {
88	        WatchdogHeartbeatCallback(msg, "chassis_driver");
89	      });
90	  heartbeat_path_tracker_sub_ = create_subscription<std_msgs::msg::Bool>(
91	      "/safety/heartbeat/path_tracker", 10,
92	      [this](const std_msgs::msg::Bool::SharedPtr msg) {
93	        WatchdogHeartbeatCallback(msg, "path_tracker");
94	      });
95	
96	  link_health_sub_ = create_subscription<amr_dispatcher_interfaces::msg::ChassisLinkHealth>(
97	      "/chassis/link_health", 10,
98	      [this](const amr_dispatcher_interfaces::msg::ChassisLinkHealth::SharedPtr msg) {
99	        chassis_healthy_ = msg->is_healthy;
100	        chassis_loss_rate_ = msg->loss_rate;
101	        // I1：链路健康数据到达打点（发布者死亡后该源将按陈旧处理）
102	        last_data_arrival_["chassis"] = std::chrono::steady_clock::now();
103	      });
104	
105	  topology_state_sub_ = create_subscription<amr_dispatcher_interfaces::msg::TopologyState>(
106	      "/dispatcher/topology_state", 10,
107	      [this](const amr_dispatcher_interfaces::msg::TopologyState::SharedPtr msg) {
108	        deadlock_active_ = msg->deadlock_detected;
109	      });
110	
111	  safe_cmd_vel_pub_ = create_publisher<geometry_msgs::msg::Twist>("/cmd_vel_safe", 10);
112	  safety_state_pub_ = create_publisher<amr_dispatcher_interfaces::msg::SafetyState>(
113	      "/safety/state", 10);
114	
115	  watchdog_timer_ = create_wall_timer(
116	      100ms, std::bind(&SafetyGateNode::WatchdogTick, this));
117	
118	  // B1 50Hz 周期发布兜底：estop/bumper/上游失联一律零速，
119	  // 正常时重放最近一次门控裁决，保证 /cmd_vel_safe 有稳定数据流。
120	  publish_timer_ = create_wall_timer(
121	      20ms, std::bind(&SafetyGateNode::PeriodicPublishTick, this));
122	
123	  RCLCPP_INFO(get_logger(), "SafetyGateNode initialized (max_vx=%.2f, max_wz=%.2f)",
124	              gate_cfg.max_linear_x_mps, gate_cfg.max_angular_z_radps);
