163	void SafetyGateNode::WatchdogTick() {
164	  if (!watchdog_ || !gate_ || !fault_supervisor_) return;
165	
166	  auto events = watchdog_->Inspect(watched_nodes_);
167	  watchdog_ok_ = events.empty();
168	  for (auto& ev : events) {
169	    gate_->PushEvent(ev);
170	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 1000,
171	                         "Watchdog event: source=%s msg=%s", ev.source.c_str(), ev.message.c_str());
172	  }
173	
174	  // C1(b)：锁存中的 estop/bumper 每 tick 重推事件以刷新 stamp。
175	  // 锁存状态可能无限期为 true，而门控事件带 TTL —— 不重推则事件先于锁存"消失"，
176	  // 事件历史与真实安全状态脱节（发布路径已由 ApplyLatchedBlocks 兜底，此处保持语义自洽）。
177	  if (estop_active_) {
178	    amr_dispatcher_core::safety::SafetyEvent evt;
179	    evt.source = "estop";
180	    evt.severity = amr_dispatcher_core::safety::SafetySeverity::kCritical;
181	    evt.message = "Emergency stop button pressed";
182	    gate_->PushEvent(evt);
183	  }
184	  if (bumper_active_) {
185	    amr_dispatcher_core::safety::SafetyEvent evt;
186	    evt.source = "bumper";
187	    evt.severity = amr_dispatcher_core::safety::SafetySeverity::kCritical;
188	    evt.message = "Front bumper triggered collision";
189	    gate_->PushEvent(evt);
190	  }
191	
192	  // 聚合四大防御源至 Fault Supervisor Engine
193	  amr_dispatcher_core::safety::MultiSourceHealthReport report;
194	  report.chassis_healthy = chassis_healthy_;
195	  report.chassis_loss_rate = chassis_loss_rate_;
196	  report.watchdog_healthy = watchdog_ok_;
197	  report.deadlock_detected = deadlock_active_;
198	  report.manual_estop = estop_active_ || bumper_active_;
199	  report.detail_message = watchdog_ok_ ? (chassis_healthy_ ? "healthy" : "chassis degraded") : "watchdog timeout";
200	
201	  // I1：时效戳只在真实数据到达时刷新（订阅回调打点），巡检周期不续命——
202	  // 上游 link_health / 心跳发布者死亡后，对应源会按陈旧降级限速。
203	  const auto fresh = MakeReportFreshness(last_data_arrival_, std::chrono::steady_clock::now(),
204	                                         heartbeat_timeout_);
205	  fault_supervisor_->UpdateMultiSourceHealth(report, fresh.chassis, fresh.watchdog);
206	  fault_supervisor_->Tick();
207	
208	  // 根据 Fault Supervisor 综合裁决建议执行动作
209	  auto rec = fault_supervisor_->recommendation();
210	  if (rec == amr_dispatcher_core::safety::SystemActionRecommendation::kEmergencyStop) {
211	    auto_fault_latched_ = true;
212	  } else if (rec == amr_dispatcher_core::safety::SystemActionRecommendation::kNone && auto_fault_latched_) {
213	    // 故障恢复且自动清除模式下解除自动急停锁存（若非人工急停按钮触发）
214	    auto_fault_latched_ = false;
215	  }
216	
217	  // 空闲周期播报安全状态：无 cmd_vel 上游时也要让 /safety/state 持续可见，
218	  // 否则 lifecycle_coordinator 的 safety_seen_ 永为 false，/system/ready 卡 INITIALIZING。
219	  PublishIdleSafetyState();
220	}
