222	void SafetyGateNode::RawCmdVelCallback(const geometry_msgs::msg::Twist::SharedPtr msg) {
223	  if (!gate_ || !fault_supervisor_) return;
224	
225	  amr_dispatcher_core::safety::CmdVelCommand cmd;
226	  cmd.linear_x_mps = msg->linear.x;
227	  cmd.linear_y_mps = msg->linear.y;
228	  cmd.angular_z_radps = msg->angular.z;
229	
230	  // 联动 Fault Supervisor 降级限速规则（M5：阈值取自 degraded_max_linear_x_mps 参数）
231	  if (fault_supervisor_->recommendation() == amr_dispatcher_core::safety::SystemActionRecommendation::kClampSpeed) {
232	    const double limit = degraded_max_linear_x_mps_;
233	    cmd.linear_x_mps = std::clamp(cmd.linear_x_mps, -limit, limit);
234	  }
235	
236	  auto decision = gate_->Evaluate(cmd);
237	  // 锁存型安全源（estop/自动故障/bumper）不依赖门控事件 TTL：事件过期 ≠ 故障解除。
238	  // 不做这层覆写，raw 路径会在事件过期后重新放行非零速度，与 50Hz 周期帧的
239	  // 零速交替发布——E-stop 按住期间底盘仍可能蠕动。
240	  ApplyLatchedBlocks(estop_active_ || auto_fault_latched_, bumper_active_, decision);
241	  last_decision_ = decision;
242	  // B1：记录 raw 到达时刻与裁决结果，供 50Hz 周期兜底判定 stale / 重放。
243	  last_raw_cmd_stamp_ = std::chrono::steady_clock::now();
244	  has_raw_cmd_stamp_ = true;
245	  has_decision_ = true;
246	
247	  geometry_msgs::msg::Twist safe_cmd;
248	  safe_cmd.linear.x = decision.linear_x_mps;
249	  safe_cmd.linear.y = decision.linear_y_mps;
250	  safe_cmd.angular.z = decision.angular_z_radps;
251	  safe_cmd_vel_pub_->publish(safe_cmd);
252	
253	  PublishSafetyState(decision);
254	}
255	
256	void SafetyGateNode::PeriodicPublishTick() {
257	  if (!safe_cmd_vel_pub_) return;
258	
259	  PeriodicPublishInput in;
260	  in.estop_or_fault = estop_active_ || auto_fault_latched_;
261	  in.bumper = bumper_active_;
262	  in.decision_critical =
263	      last_decision_.severity == amr_dispatcher_core::safety::SafetySeverity::kCritical;
264	  in.has_decision = has_decision_;
265	  in.has_last_raw_stamp = has_raw_cmd_stamp_;
266	  in.last_raw_stamp = last_raw_cmd_stamp_;
267	  in.now = std::chrono::steady_clock::now();
268	  in.heartbeat_timeout = heartbeat_timeout_;
269	  in.last_linear_x_mps = last_decision_.linear_x_mps;
270	  in.last_linear_y_mps = last_decision_.linear_y_mps;
271	  in.last_angular_z_radps = last_decision_.angular_z_radps;
272	
273	  const auto out = ComputePeriodicPublish(in);
274	  if (out.kind == PeriodicPublishKind::kSkip) return;
275	
276	  geometry_msgs::msg::Twist safe_cmd;
277	  safe_cmd.linear.x = out.linear_x_mps;
278	  safe_cmd.linear.y = out.linear_y_mps;
279	  safe_cmd.angular.z = out.angular_z_radps;
280	  safe_cmd_vel_pub_->publish(safe_cmd);
281	}
282	
283	void SafetyGateNode::PublishIdleSafetyState() {
284	  // 无任何运动指令时构造零速裁决：allowed 由多源健康聚合决定，
285	  // reason 标注 idle 以便运维区分"门控放行"与"门控阻断"。
286	  amr_dispatcher_core::safety::CmdVelGateDecision idle;
287	  const bool effective_estop = estop_active_ || auto_fault_latched_;
288	  idle.allowed = watchdog_ok_ && !effective_estop && !bumper_active_ && !manual_takeover_active_;
289	  idle.reason = idle.allowed ? "idle" : "idle_blocked";
290	  idle.severity = effective_estop || bumper_active_ ? amr_dispatcher_core::safety::SafetySeverity::kCritical
291	                                                 : (watchdog_ok_ ? amr_dispatcher_core::safety::SafetySeverity::kInfo
292	                                                                 : amr_dispatcher_core::safety::SafetySeverity::kWarn);
293	  PublishSafetyState(idle);
294	}
295	
296	void SafetyGateNode::PublishSafetyState(const amr_dispatcher_core::safety::CmdVelGateDecision& decision) {
297	  amr_dispatcher_interfaces::msg::SafetyState state_msg;
298	  state_msg.header.stamp = now();
299	  state_msg.motion_allowed = decision.allowed;
300	  state_msg.reason = decision.reason;
301	
302	  if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kCritical) {
303	    state_msg.severity = "CRITICAL";
304	    state_msg.speed_scale = 0.0;
305	  } else if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kWarn) {
306	    state_msg.severity = "WARN";
307	    state_msg.speed_scale = 0.3;
308	  } else {
309	    state_msg.severity = "INFO";
310	    state_msg.speed_scale = 1.0;
311	  }
312	
313	  if (estop_active_ || auto_fault_latched_) state_msg.active_sources.push_back("estop");
314	  if (bumper_active_) state_msg.active_sources.push_back("bumper");
315	  if (manual_takeover_active_) state_msg.active_sources.push_back("manual_takeover");
316	  if (!state_msg.active_sources.empty()) {
317	    state_msg.active_stop_source = state_msg.active_sources.front();
318	  }
319	
320	  safety_state_pub_->publish(state_msg);
321	}
