107	  // B1 指令龄兜底：后端在线但上游超过 cmd_stale_timeout_ms 未再发指令，
108	  // 主动写零帧，防止底盘沿用最后一次非零指令继续运动。
109	  if (has_cmd_stamp_) {
110	    const auto age = std::chrono::steady_clock::now() - last_cmd_stamp_;
111	    if (age > cmd_stale_timeout_) {
112	      amr_dispatcher_core::chassis::ChassisCommand zero_cmd;
113	      std::string zero_err;
114	      backend_ctrl_->current()->WriteCommand(zero_cmd, &zero_err);
