140	  // 解析失败行计入丢帧
141	  const auto invalid_lines = text_stream_.InvalidLineCount();
142	  for (std::size_t i = 0; i < invalid_lines; ++i) {
143	    backend_ctrl_->RecordLoss();
144	  }
