161	    nav_msgs::msg::Odometry odom_msg;
162	    odom_msg.header.stamp = now;
163	    odom_msg.header.frame_id = odom_frame_id_;
164	    odom_msg.child_frame_id = base_frame_id_;
165	    odom_msg.pose.pose.position.x = o.x_m;
166	    odom_msg.pose.pose.position.y = o.y_m;
167	    odom_msg.pose.pose.position.z = 0.0;
168	
169	    tf2::Quaternion q;
170	    q.setRPY(0.0, 0.0, o.yaw_rad);
171	    odom_msg.pose.pose.orientation.x = q.x();
172	    odom_msg.pose.pose.orientation.y = q.y();
173	    odom_msg.pose.pose.orientation.z = q.z();
174	    odom_msg.pose.pose.orientation.w = q.w();
175	
