272	CallbackReturn DispatcherNode::on_activate(const rclcpp_lifecycle::State& /*state*/) {
273	  state_pub_->on_activate();
274	  event_pub_->on_activate();
275	  plan_pub_->on_activate();
276	  topology_pub_->on_activate();
277	  for (auto& [vehicle_id, pub] : vda5050_order_pubs_) {
278	    pub->on_activate();  // Task 6：send_order 发布端随节点激活（未激活则 publish 为空操作）
279	  }
280	
281	  const double sched_hz = get_parameter("schedule_rate_hz").as_double();
282	  schedule_timer_ = create_wall_timer(
283	      std::chrono::duration<double>(1.0 / sched_hz),
284	      std::bind(&DispatcherNode::ScheduleTick, this));
285	
286	  const double deadlock_hz = get_parameter("deadlock_check_rate_hz").as_double();
287	  deadlock_timer_ = create_wall_timer(
288	      std::chrono::duration<double>(1.0 / deadlock_hz),
289	      std::bind(&DispatcherNode::DeadlockTick, this));
290	
