```cpp
#pragma once

#include <string>
#include <cctype>

namespace amr_dispatcher_ros {

// ROS 2 名称合法性：车辆 id 必须是 [A-Za-z_][A-Za-z0-9_]*
inline bool IsValidVehicleId(const std::string& vehicle_id) {
  if (vehicle_id.empty()) return false;
  const char first = vehicle_id[0];
  if (!(std::isalpha(static_cast<unsigned char>(first)) || first == '_')) return false;
  for (std::size_t i = 1; i < vehicle_id.size(); ++i) {
    const char c = vehicle_id[i];
    if (!(std::isalnum(static_cast<unsigned char>(c)) || c == '_')) return false;
  }
  return true;
}

// per-vehicle 话题派生：legacy 话题 + "/" + vehicle_id
inline std::string DeriveVehicleTopic(const std::string& legacy_topic, const std::string& vehicle_id) {
  if (vehicle_id.empty()) return legacy_topic;
  if (legacy_topic.empty()) return "/" + vehicle_id;
  if (legacy_topic.back() == '/') return legacy_topic + vehicle_id;
  return legacy_topic + "/" + vehicle_id;
}

// 显式覆盖 > 派生 > 遗留名
inline std::string ResolveVehicleTopic(const std::string& explicit_topic, const std::string& legacy_topic, const std::string& vehicle_id) {
  if (!explicit_topic.empty()) return explicit_topic;
  return DeriveVehicleTopic(legacy_topic, vehicle_id);
}
}
