    ResolveVehicleTopic(get_parameter("cmd_vel_topic").as_string(), "/cmd_vel_safe", vehicle_id_);
odom_topic_ = ResolveVehicleTopic(get_parameter("odom_topic").as_string(), "/odom", vehicle_id_);
